//! Renders [`Definitions`] as a single Python module of `trezorlib` message
//! classes.

use super::model::{Definitions, Field, Message};
use std::fmt::Write;

const HEADER: &str = "\
# Automatically generated by pb2py
# fmt: off
# isort:skip_file

from enum import IntEnum
from typing import Sequence, Optional

from trezorlib import protobuf
";

pub fn render(defs: &Definitions) -> String {
    let mut out = String::from(HEADER);

    for e in &defs.enums {
        write!(out, "\n\nclass {}(IntEnum):\n", e.name).unwrap();
        for (name, number) in &e.values {
            writeln!(out, "    {name} = {number}").unwrap();
        }
    }

    for message in &defs.messages {
        render_message(&mut out, message);
    }

    out
}

fn render_message(out: &mut String, message: &Message) {
    write!(
        out,
        "\n\nclass {}(protobuf.MessageType):\n    MESSAGE_WIRE_TYPE = None\n",
        message.name
    )
    .unwrap();

    if message.fields.is_empty() {
        return;
    }

    out.push_str("    FIELDS = {\n");
    for f in &message.fields {
        let python_bool = |b: bool| if b { "True" } else { "False" };
        write!(
            out,
            "        {}: protobuf.Field(\"{}\", \"{}\", repeated={}, required={}",
            f.number,
            f.name,
            f.type_name,
            python_bool(f.repeated),
            python_bool(f.required),
        )
        .unwrap();
        if !f.required {
            write!(out, ", default={}", f.default_repr).unwrap();
        }
        out.push_str("),\n");
    }
    out.push_str("    }\n\n    def __init__(\n        self,\n        *,\n");

    let required = || message.fields.iter().filter(|f| f.required);
    let repeated = || message.fields.iter().filter(|f| f.repeated);
    let optional = || message.fields.iter().filter(|f| f.optional());

    for f in required() {
        writeln!(out, "        {}: \"{}\",", f.name, f.python_type).unwrap();
    }
    for f in repeated() {
        writeln!(
            out,
            "        {}: Optional[Sequence[\"{}\"]] = None,",
            f.name, f.python_type
        )
        .unwrap();
    }
    for f in optional() {
        writeln!(
            out,
            "        {}: Optional[\"{}\"] = {},",
            f.name, f.python_type, f.default_repr
        )
        .unwrap();
    }
    out.push_str("    ) -> None:\n");

    for f in repeated() {
        writeln!(
            out,
            "        self.{0}: Sequence[\"{1}\"] = {0} if {0} is not None else []",
            f.name, f.python_type
        )
        .unwrap();
    }
    for f in required().chain(optional()) {
        render_assign(out, f);
    }
}

fn render_assign(out: &mut String, f: &Field) {
    writeln!(out, "        self.{0} = {0}", f.name).unwrap();
}
